export default {async fetch(req,env){
 const u=new URL(req.url);if(u.pathname.startsWith('/api/relay/'))return relay(req,env);if(u.pathname.startsWith('/api/ranked/'))return ranked(req,env);if(!u.pathname.startsWith('/api/rooms'))return new Response(HTML,{headers:{'content-type':'text/html;charset=utf-8'}});
 try{
 const token=req.headers.get('x-rally-token');if(!token||!/^[a-f0-9]{48}$/.test(token))return response({error:'Invalid match token'},401);
 const parts=u.pathname.split('/').filter(Boolean),code=parts[2],join=parts[3]==='join',bucket=env.BUCKET;
 let body={};if(req.method==='POST'||req.method==='PATCH'){let raw=await req.text();if(raw.length>100000)return response({error:'Request too large'},413);body=raw?JSON.parse(raw):{};}
 if(req.method==='POST'&&!code){
 if(body.offer?.type!=='offer'||typeof body.offer.sdp!=='string')return response({error:'Invalid offer'},400);
 const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
 for(let attempt=0;attempt<12;attempt++){
 const c=Array.from(crypto.getRandomValues(new Uint8Array(4)),v=>alphabet[v%alphabet.length]).join('');
 const data={host:token,offer:body.offer,expiresAt:Date.now()+900000,revision:0,restartAt:0,relayId:crypto.randomUUID(),signalKey:c+'/'+crypto.randomUUID()};
 // Claim atomically: a short-code collision must never replace someone else's room.
 const created=await bucket.put(c+'/room',JSON.stringify(data),{onlyIf:{etagDoesNotMatch:'*'}});
 if(created)return response({code:c,expiresAt:data.expiresAt,revision:0});
 }
 return response({error:'Could not reserve a room code. Please try again.'},503);}
 if(!/^(?:[A-Z]{4}|[A-HJ-NP-Z2-9]{8})$/.test(code||''))return response({error:'Invalid room code'},400);
 const obj=await bucket.get(code+'/room');if(!obj)return response({error:'Match not found. Create a new match.'},404);let room=await obj.json();if(room.expiresAt<Date.now())return response({error:'Invite expired. Create a new match.'},410);
 if(join&&req.method==='POST'){
 if(room.host===token)return response({error:'Open the invite on your friend’s device.'},400);
 if(room.guest&&room.guest!==token)return response({error:'This match already has two players.'},409);
 room.guest=token;const saved=await bucket.put(code+'/room',JSON.stringify(room),{onlyIf:{etagMatches:obj.etag}});if(!saved)return response({error:'Room changed. Try joining again.'},409);
 const cs=await candidates(bucket,room.signalKey||code,'host');return response({relay:!!room.relay,offer:room.offer,candidates:cs,revision:room.revision||0});}
 const role=room.host===token?'host':room.guest===token?'guest':null;if(!role)return response({error:'You are not in this match.'},401);
 if(req.method==='DELETE'){if(role==='host')await bucket.delete(code+'/room');return response({ok:true});}
 if(req.method==='PATCH'){
 const revision=room.revision||0;
 if(body.relay){
  if(!room.guest)return response({error:'Wait for your friend to join.'},409);
  if(!room.relayId)room.relayId=crypto.randomUUID();room.relay=true;room.expiresAt=Date.now()+1800000;
  const saved=await bucket.put(code+'/room',JSON.stringify(room),{onlyIf:{etagMatches:obj.etag}});if(!saved)return response({error:'Room changed. Retry.'},409);
  await env.DB.prepare('INSERT INTO relay_matches(id,host,guest,expires) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET expires=excluded.expires').bind(room.relayId,room.host,room.guest,room.expiresAt).run();
  return response({relayId:room.relayId});
 }
 if(body.offer){
  if(role!=='host'||body.offer.type!=='offer'||typeof body.offer.sdp!=='string')return response({error:'Only the host can restart the connection.'},403);
  if((body.revision||0)!==revision)return response({error:'Connection has a newer revision.'},409);
  room.offer=body.offer;room.revision=revision+1;room.signalKey=code+'/'+crypto.randomUUID();room.expiresAt=Date.now()+1800000;
  const saved=await bucket.put(code+'/room',JSON.stringify(room),{onlyIf:{etagMatches:obj.etag}});if(!saved)return response({error:'Room changed. Retry reconnecting.'},409);
  return response({revision:room.revision,restartAt:room.restartAt||0});
 }
 if(body.restart||body.heartbeat){
  if(body.restart)room.restartAt=Date.now();room.expiresAt=Date.now()+1800000;
  const saved=await bucket.put(code+'/room',JSON.stringify(room),{onlyIf:{etagMatches:obj.etag}});if(!saved)return response({error:'Room changed. Retry.'},409);
  return response({revision,restartAt:room.restartAt||0,expiresAt:room.expiresAt});
 }
 if((body.revision||0)!==revision)return response({error:'Discarded data from an old connection.'},409);
 if(body.answer){if(role!=='guest'||body.answer.type!=='answer')return response({error:'Invalid answer'},400);await bucket.put((room.signalKey||code)+'/answer',JSON.stringify(body.answer));}
 if(body.candidates){if(!Array.isArray(body.candidates)||body.candidates.length>32)return response({error:'Invalid candidates'},400);await bucket.put((room.signalKey||code)+'/ice/'+role+'/'+crypto.randomUUID(),JSON.stringify(body.candidates));}return response({ok:true,revision});}
 if(req.method==='GET'){const answer=await bucket.get((room.signalKey||code)+'/answer');return response({joined:!!room.guest,relay:!!room.relay,offer:role==='guest'?room.offer:undefined,revision:room.revision||0,restartAt:room.restartAt||0,answer:answer?await answer.json():null,candidates:await candidates(bucket,room.signalKey||code,role==='host'?'guest':'host')});}
 return response({error:'Method not allowed'},405);
 }catch{return response({error:'Match service unavailable. Please try again.'},500);}
}};
async function candidates(bucket,code,role){const list=await bucket.list({prefix:code+'/ice/'+role+'/'});const values=await Promise.all(list.objects.slice(0,100).map(async x=>(await bucket.get(x.key)).json()));return values.flat();}

async function ranked(request,env){
 const json=(v,status=200)=>Response.json(v,{status,headers:{'cache-control':'no-store'}});
 try{
 const raw=request.headers.get('x-player-token')||'';if(!/^[a-f0-9]{64}$/.test(raw))return json({error:'A saved player profile is required.'},401);
 const id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw))),x=>x.toString(16).padStart(2,'0')).join('');
 const db=env.DB,now=Date.now(),path=new URL(request.url).pathname.split('/').pop(),method=request.method;
 const stmt=(sql,...args)=>db.prepare(sql).bind(...args),one=(sql,...args)=>stmt(sql,...args).first();
 let body={};if(method==='POST'){const t=await request.text();if(t.length>4096)return json({error:'Request too large'},413);body=t?JSON.parse(t):{}}
 let player=await one('SELECT * FROM rank_players WHERE id=?',id);
 if(!player){await stmt('INSERT OR IGNORE INTO rank_players(id,name,created) VALUES(?,?,?)',id,'Player '+id.slice(0,4).toUpperCase(),now).run();player=await one('SELECT * FROM rank_players WHERE id=?',id)}
 if(path==='profile'){
 if(method==='POST'){const name=String(body.name||'').trim().replace(/[\u0000-\u001f<>]/g,'').slice(0,24);if(!name)return json({error:'Choose a player name.'},400);await stmt('UPDATE rank_players SET name=? WHERE id=?',name,id).run();player.name=name}
 return json({player:publicPlayer(player)});
 }
 let match=await one('SELECT m.* FROM rank_matches m JOIN rank_seats s ON s.match=m.id WHERE s.player=?',id);
 if(path==='queue'&&method==='DELETE'){
 await stmt('DELETE FROM rank_queue WHERE player=?',id).run();
 if(match){if(match.status==='active'&&match.host_report===null&&match.guest_report===null){await settleRank(db,match,match.host===id?1:0,'forfeit')}else if(match.status==='waiting'){await db.batch([stmt("UPDATE rank_matches SET status='cancelled',reason='Player left before connection' WHERE id=? AND status='waiting'",match.id),stmt("DELETE FROM rank_seats WHERE player=? AND match=?",id,match.id)])}}
 await stmt("DELETE FROM rank_seats WHERE player=? AND EXISTS(SELECT 1 FROM rank_matches WHERE id=rank_seats.match AND status IN ('finished','cancelled','disputed'))",id).run();
 return json({cancelled:true,player:publicPlayer(await one('SELECT * FROM rank_players WHERE id=?',id))});
 }
 if(path==='queue'&&method==='POST'&&!match){
 await stmt('INSERT INTO rank_queue(player,entered,seen) VALUES(?,?,?) ON CONFLICT(player) DO UPDATE SET seen=excluded.seen',id,now,now).run();
 const q=await one('SELECT * FROM rank_queue WHERE player=?',id),range=Math.min(700,150+(now-q.entered)/1000*5);
 const other=await one('SELECT p.*,q.entered FROM rank_queue q JOIN rank_players p ON p.id=q.player WHERE q.player<>? AND q.seen>? AND NOT EXISTS(SELECT 1 FROM rank_seats WHERE player=q.player) AND ABS(p.rating-?)<=? ORDER BY ABS(p.rating-?),q.entered LIMIT 1',id,now-15000,player.rating,range,player.rating);
 if(other){const mid=crypto.randomUUID();try{
 await db.batch([
 stmt('INSERT INTO rank_matches(id,host,guest,host_rating,guest_rating,created,host_seen,guest_seen) SELECT ?,?,?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM rank_queue WHERE player=? AND seen>?) AND EXISTS(SELECT 1 FROM rank_queue WHERE player=? AND seen>?)',mid,id,other.id,player.rating,other.rating,now,now,now,id,now-15000,other.id,now-15000),
 stmt('INSERT INTO rank_seats(player,match) SELECT ?,? WHERE EXISTS(SELECT 1 FROM rank_matches WHERE id=?)',id,mid,mid),
 stmt('INSERT INTO rank_seats(player,match) SELECT ?,? WHERE EXISTS(SELECT 1 FROM rank_matches WHERE id=?)',other.id,mid,mid),
 stmt('DELETE FROM rank_queue WHERE player IN (?,?) AND EXISTS(SELECT 1 FROM rank_matches WHERE id=?)',id,other.id,mid)]);
 }catch{/* Another queue request reserved one of these players first; reload the winning match. */}
 match=await one('SELECT m.* FROM rank_matches m JOIN rank_seats s ON s.match=m.id WHERE s.player=?',id);
 }
 }
 if(match){
 const host=match.host===id,own=host?'host':'guest';
 if(body.matchId&&body.matchId!==match.id)return json({error:'This match is no longer current.'},409);
 if(path==='room'&&method==='POST'){
 if(!host||match.status!=='waiting'||!/^[A-Z]{4}$/.test(body.room||''))return json({error:'Invalid ranked room'},400);
 const room=await env.BUCKET.get(body.room+'/room');if(!room)return json({error:'Room not found'},404);
 const roomData=await room.json();if(roomData.host!==body.roomToken)return json({error:'Room ownership mismatch'},403);
 await stmt("UPDATE rank_matches SET room=? WHERE id=? AND status='waiting'",body.room,match.id).run();
 }
 if(path==='start'&&method==='POST'&&match.status==='waiting'){
 await stmt(`UPDATE rank_matches SET ${own}_started=1,${own}_seen=? WHERE id=? AND status='waiting'`,now,match.id).run();
 await stmt("UPDATE rank_matches SET status='active' WHERE id=? AND status='waiting' AND host_started=1 AND guest_started=1",match.id).run();
 }
 if(path==='result'&&method==='POST'&&match.status==='waiting')return json({error:'Waiting for both players to connect.'},409);
 if(path==='result'&&method==='POST'&&match.status==='active'){
 const winner=Number(body.winner),sets=body.sets;
 if(![0,1].includes(winner)||!Array.isArray(sets)||sets.length!==2||sets[winner]!==2||![0,1].includes(sets[1-winner]))return json({error:'A completed best-of-three match is required.'},400);
 await stmt(`UPDATE rank_matches SET ${own}_report=? WHERE id=? AND status='active' AND ${own}_report IS NULL`,winner,match.id).run();
 const m=await one('SELECT * FROM rank_matches WHERE id=?',match.id);
 if(m.host_report!==null&&m.guest_report!==null){if(m.host_report===m.guest_report)await settleRank(db,m,m.host_report,'completed');else await stmt("UPDATE rank_matches SET status='disputed',reason='Results did not agree; no rating change' WHERE id=? AND status='active'",match.id).run()}
 }
 if(path==='ack'&&method==='POST')await stmt("DELETE FROM rank_seats WHERE player=? AND match=? AND EXISTS(SELECT 1 FROM rank_matches WHERE id=? AND status IN ('finished','cancelled','disputed'))",id,match.id,match.id).run();
 match=await one('SELECT * FROM rank_matches WHERE id=?',match.id);
 if(['waiting','active'].includes(match.status)){
 await stmt(`UPDATE rank_matches SET ${own}_seen=? WHERE id=?`,now,match.id).run();
 const opponentSeen=host?match.guest_seen:match.host_seen;
 if(now-opponentSeen>90000){if(match.status==='active'&&match.host_report===null&&match.guest_report===null)await settleRank(db,match,host?0:1,'opponent disconnected');else await stmt("UPDATE rank_matches SET status='cancelled',reason=? WHERE id=? AND status IN ('waiting','active')",match.status==='active'?'Result could not be confirmed; no rating change':'Opponent did not connect',match.id).run()}
 match=await one('SELECT * FROM rank_matches WHERE id=?',match.id);
 }
 const opponent=await one('SELECT * FROM rank_players WHERE id=?',host?match.guest:match.host);
 return json({player:publicPlayer(await one('SELECT * FROM rank_players WHERE id=?',id)),match:{id:match.id,role:host?0:1,room:match.room,status:match.status,opponent:publicPlayer(opponent),winner:match.winner,delta:match.delta===null?null:(host?match.delta:-match.delta),reason:match.reason}});
 }
 if(path==='status')await stmt('UPDATE rank_queue SET seen=? WHERE player=?',now,id).run();
 const q=await one('SELECT * FROM rank_queue WHERE player=?',id);
 return json({player:publicPlayer(player),queued:!!q,entered:q?.entered||null});
 }catch{return json({error:'Ranked service is temporarily unavailable. Please retry.'},500)}
}
function publicPlayer(p){return {name:p.name,rating:p.rating,wins:p.wins,losses:p.losses,rank:rankName(p.rating)}}
function rankName(r){return r>=1900?'Master':r>=1700?'Diamond':r>=1500?'Platinum':r>=1300?'Gold':r>=1100?'Silver':'Bronze'}
async function settleRank(db,m,winner,reason){
 const expected=1/(1+10**((m.guest_rating-m.host_rating)/400)),delta=Math.round(32*((winner===0?1:0)-expected));
 const st=(sql,...args)=>db.prepare(sql).bind(...args);
 // One transactional batch claims settlement, changes both ratings, and marks it final.
 await db.batch([
 st("UPDATE rank_matches SET status='settling',winner=?,delta=?,reason=? WHERE id=? AND status='active'",winner,delta,reason,m.id),
 st("UPDATE rank_players SET rating=MAX(0,rating+?),wins=wins+?,losses=losses+? WHERE id=? AND EXISTS(SELECT 1 FROM rank_matches WHERE id=? AND status='settling')",delta,winner===0?1:0,winner===0?0:1,m.host,m.id),
 st("UPDATE rank_players SET rating=MAX(0,rating+?),wins=wins+?,losses=losses+? WHERE id=? AND EXISTS(SELECT 1 FROM rank_matches WHERE id=? AND status='settling')",-delta,winner===1?1:0,winner===1?0:1,m.guest,m.id),
 st("UPDATE rank_matches SET status='finished' WHERE id=? AND status='settling'",m.id)]);
}

async function relay(req,env){
 try{
  if(req.method!=='POST')return response({error:'Method not allowed'},405);
  const id=new URL(req.url).pathname.split('/').pop(),token=req.headers.get('x-rally-token')||'';
  if(!/^[a-f0-9-]{36}$/.test(id)||!/^[a-f0-9]{48}$/.test(token))return response({error:'Invalid match credentials'},401);
  const raw=await req.text();if(raw.length>24000)return response({error:'Packet too large'},413);
  const p=JSON.parse(raw);if(!Number.isSafeInteger(p.seq)||p.seq<1||!p.game||!['s','i'].includes(p.game.t)||!Array.isArray(p.controls)||p.controls.length>32)return response({error:'Invalid game packet'},400);
  const side=p.game.t==='s'?'host':'guest',other=side==='host'?'guest':'host',now=Date.now();
  const result=await env.DB.prepare(`UPDATE relay_matches SET ${side}_data=CASE WHEN ${side}_seq<? THEN ? ELSE ${side}_data END,${side}_seen=CASE WHEN ${side}_seq<? THEN ? ELSE ${side}_seen END,${side}_seq=MAX(${side}_seq,?),expires=? WHERE id=? AND ${side}=? AND expires>=? RETURNING ${other}_data AS data,${other}_seen AS seen`).bind(p.seq,raw,p.seq,now,p.seq,now+1800000,id,token,now).first();
  if(!result){
   const row=await env.DB.prepare('SELECT host,guest,expires FROM relay_matches WHERE id=?').bind(id).first();
   if(!row||row.expires<now)return response({error:'Match expired. Create a new room.'},410);
   if(row.host!==token&&row.guest!==token)return response({error:'You are not in this match.'},401);
   return response({error:'Invalid game packet'},400);
  }
  return response({peer:result.data?JSON.parse(result.data):null,peerSeen:result.seen,peerAgeMs:result.data?Math.max(0,Date.now()-result.seen):null});
 }catch{return response({error:'Server connection unavailable'},500)}
}
